"""
Generate resources/js/creatures/builtins.js from the creature settings and each strip's
measured description, so display sizes and hitboxes always match the artwork.
"""

from creatures import CREATURES, DISPLAY_SCALE

HEADER = """/**
 * Built-in creatures. GENERATED by bin/sprites/build.py; edit bin/sprites/creatures.py instead.
 *
 * Sprite strips (resources/sprites/<name>.png) have 14 frames: walk/swim 0-3, idle 4-6,
 * sleep 7-9, pet 10-11, carried 12-13, facing right, feet on the cell's bottom edge. Each
 * sprite ships as its own stylesheet (resources/css/creatures/<name>.css), so skins use
 * `className` rather than `src`.
 *
 * Hitboxes are the strips' measured footprints; display sizes keep every creature at the
 * same pixel scale (2/3 of the source cell).
 */
"""


def _object(values):
    return '{ ' + ', '.join(f'{key}: {value}' for key, value in values.items()) + ' }'


def render(descriptions):
    lines = [HEADER.rstrip('\n'), 'export const builtInCreatures = {']

    for name, settings in CREATURES.items():
        data = descriptions[name]
        cell = data['frameWidth']
        size = round(cell * DISPLAY_SCALE)
        scale = size / cell

        lines += [
            f'    {name}: {{',
            f"        title: '{settings['title']}',",
            f"        label: '{settings['label']}',",
            f'        width: {size},',
            f'        height: {size},',
            f"        speed: {settings['speed']},",
            f"        behavior: '{settings['behavior']}',",
            '        hitboxes: {',
        ]
        for key, footprint in data['footprints'].items():
            lines.append(f'            {key}: {_object({k: round(v * scale) for k, v in footprint.items()})},')
        lines += [
            '        },',
            '        skin: {',
            f"            className: 'critters-skin-{name}',",
            f'            frameWidth: {cell},',
            f"            frameHeight: {data['frameHeight']},",
            f"            frameCount: {data['frameCount']},",
            f"            facing: '{data['facing']}',",
            '            animations: {',
        ]
        for key, animation in data['animations'].items():
            lines.append(f"                {key}: {{ frames: [{', '.join(map(str, animation['frames']))}], fps: {animation['fps']} }},")
        lines += ['            },', '        },', '    },']

    lines.append('}')

    return '\n'.join(lines) + '\n'
